import type { DatabaseSync } from "node:sqlite";
import { db } from "./scanAccess";
import type { AnalysisResult, Grade, LeaderboardEntry, LeaderboardPage, LeaderboardPlacement } from "./types";

export const LEADERBOARD_PAGE_SIZE = 25;

/** Timestamps are generated by the database, in UTC. */
const NOW = "strftime('%Y-%m-%dT%H:%M:%fZ', 'now')";

/** Best score first; whoever reached a score first wins a tie. A total order, so ranks never collide. */
const RANK_ORDER = "score DESC, scored_at ASC, host ASC";

// host is the natural key: one row per site, however many times it is scanned.
// hidden is a takedown flag. A row is hidden rather than deleted so that
// rescanning the site cannot silently bring it back.
const SCHEMA = `
CREATE TABLE IF NOT EXISTS leaderboard (
  host TEXT PRIMARY KEY CHECK (length(host) BETWEEN 3 AND 253),
  score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100),
  grade TEXT NOT NULL CHECK (grade IN ('A', 'B', 'C', 'D', 'F')),
  scans INTEGER NOT NULL DEFAULT 1,
  hidden INTEGER NOT NULL DEFAULT 0 CHECK (hidden IN (0, 1)),
  scored_at TEXT NOT NULL DEFAULT (${NOW}),
  created_at TEXT NOT NULL DEFAULT (${NOW}),
  updated_at TEXT NOT NULL DEFAULT (${NOW})
);
CREATE INDEX IF NOT EXISTS leaderboard_rank ON leaderboard (score DESC, scored_at ASC, host ASC) WHERE hidden = 0;
`;

// Keeps the best score. Every SET expression reads the pre-update row, so the
// three CASE comparisons all see the old score regardless of assignment order.
const UPSERT = `
INSERT INTO leaderboard (host, score, grade) VALUES (?, ?, ?)
ON CONFLICT(host) DO UPDATE SET
  scans = scans + 1,
  updated_at = ${NOW},
  grade = CASE WHEN excluded.score > score THEN excluded.grade ELSE grade END,
  scored_at = CASE WHEN excluded.score > score THEN ${NOW} ELSE scored_at END,
  score = CASE WHEN excluded.score > score THEN excluded.score ELSE score END
`;

const GRADES: readonly Grade[] = ["A", "B", "C", "D", "F"];
const IPV4 = /^\d{1,3}(\.\d{1,3}){3}$/;
// Two or more DNS labels; IDNs arrive already punycoded, so ASCII only.
const HOSTNAME = /^(?=.{3,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{1,62}$/;

const initialised = new WeakSet<DatabaseSync>();

function leaderboardDb(): DatabaseSync {
  const database = db();
  if (!initialised.has(database)) {
    database.exec(SCHEMA);
    initialised.add(database);
  }
  return database;
}

function asGrade(value: unknown): Grade {
  return GRADES.find((grade) => grade === value) ?? "F";
}

/**
 * The leaderboard key for a URL: lower-case hostname without `www.`, so
 * `example.com` and `www.example.com` are one site. Returns null for anything
 * that is not a public-looking domain name (IP addresses, bare labels).
 */
export function leaderboardHost(rawUrl: string): string | null {
  let hostname: string;
  try {
    hostname = new URL(rawUrl).hostname.toLowerCase();
  } catch {
    return null;
  }
  hostname = hostname.replace(/\.$/, "").replace(/^www\./, "");
  if (IPV4.test(hostname) || hostname.startsWith("[")) return null;
  return HOSTNAME.test(hostname) ? hostname : null;
}

/**
 * Lists a finished scan on the leaderboard. Returns where it landed, or null
 * when the scan is not eligible: the page must have returned HTTP 200 (a 404
 * page is not a site worth ranking), the host must be a real domain name, and
 * it must not have been hidden by the site owner or an admin.
 */
export function recordScan(result: AnalysisResult): LeaderboardPlacement | null {
  if (result.checks.find((check) => check.id === "http-ok")?.status !== "pass") return null;
  const host = leaderboardHost(result.finalUrl);
  if (!host) return null;

  const database = leaderboardDb();
  const previous = database.prepare("SELECT score, hidden FROM leaderboard WHERE host = ?").get(host);
  if (previous && Number(previous.hidden) === 1) return null;

  database.prepare(UPSERT).run(host, result.score, result.grade);

  const row = database.prepare("SELECT score, grade, scored_at FROM leaderboard WHERE host = ?").get(host);
  if (!row) return null;
  const ahead = database
    .prepare(
      `SELECT COUNT(*) AS n FROM leaderboard
       WHERE hidden = 0 AND (score > ? OR (score = ? AND (scored_at < ? OR (scored_at = ? AND host < ?))))`,
    )
    .get(row.score, row.score, row.scored_at, row.scored_at, host);
  const total = database.prepare("SELECT COUNT(*) AS n FROM leaderboard WHERE hidden = 0").get();

  return {
    host,
    rank: Number(ahead?.n ?? 0) + 1,
    total: Number(total?.n ?? 0),
    score: Number(row.score),
    grade: asGrade(row.grade),
    improved: !previous || result.score > Number(previous.score),
  };
}

/** One page of the board. Out-of-range or non-numeric page numbers are clamped, never an error. */
export function getLeaderboardPage(requestedPage: number): LeaderboardPage {
  const database = leaderboardDb();
  const total = Number(database.prepare("SELECT COUNT(*) AS n FROM leaderboard WHERE hidden = 0").get()?.n ?? 0);
  const pages = Math.max(1, Math.ceil(total / LEADERBOARD_PAGE_SIZE));
  const page = Math.min(Math.max(1, Math.trunc(requestedPage) || 1), pages);
  const offset = (page - 1) * LEADERBOARD_PAGE_SIZE;

  const rows = database
    .prepare(
      `SELECT host, score, grade, scans, scored_at FROM leaderboard
       WHERE hidden = 0 ORDER BY ${RANK_ORDER} LIMIT ? OFFSET ?`,
    )
    .all(LEADERBOARD_PAGE_SIZE, offset);

  const entries: LeaderboardEntry[] = rows.map((row, index) => ({
    rank: offset + index + 1,
    host: String(row.host),
    score: Number(row.score),
    grade: asGrade(row.grade),
    scans: Number(row.scans),
    scoredAt: String(row.scored_at),
  }));

  return { entries, total, page, pages, pageSize: LEADERBOARD_PAGE_SIZE };
}
